    n = len(str2)
    # Create a table to store lengths of longest common subsequence of str1[0..i] and str2[0..j]
    table = [[0 for x in range(n+1)] for y in range(m+1)]
    # Initialize the first row and column of the table
    for I in range(m+1):
        table[i][0] = 0
    for j in range(n+1):
        table[0][j] = 0
    # Fill the rest of the table
    for I in range(1, m+1):
        for j in range(1, n+1):
            if str1[i-1] == str2[j-1]:
                table[i][j] = table[i-1][j-1] + 1
            else:
                table[i][j] = max(table[i-1][j], table[i][j-1])
    # Find the longest common subsequence
    longest = []
    i = m
    j = n
    while i > 0 and j > 0:
        if str1[i-1] == str2[j-1]:
            longest.append(str1[i-1])
            i -= 1
            j -= 1
        elif table[i-1][j] > table[i][j-1]:
            i -= 1
        else:
            j -= 1
    # Reverse the longest common subsequence
    longest.reverse()
    return ''.join(longest)

